// === Profile Image with base64 fallback ===
(function(){
  const b64 = "";
  const imgs = document.querySelectorAll('#heroImg, #tentangImg');
  imgs.forEach(img => {
    img.onerror = function(){ this.src = 'data:image/jpeg;base64,' + b64; this.onerror=null; };
    // Try loading from file first; if not found, use base64
    img.src = img.src || 'data:image/jpeg;base64,' + b64;
  });
})();

